package com.oanarinaldi.wakemeup;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.time.*;import java.util.*;
final class AlarmScheduler {
 static PendingIntent operation(Context c,String id){return PendingIntent.getBroadcast(c,0,new Intent(c,AlarmReceiver.class).setAction("wake:"+id).putExtra("id",id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void at(Context c,String id,long at){if(at<=System.currentTimeMillis())return;AlarmManager am=c.getSystemService(AlarmManager.class);PendingIntent show=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);if(id.equals("bedtime"))am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,operation(c,id));else am.setAlarmClock(new AlarmManager.AlarmClockInfo(at,show),operation(c,id));}
 static void cancel(Context c,String id){c.getSystemService(AlarmManager.class).cancel(operation(c,id));c.getSystemService(NotificationManager.class).cancel(id.hashCode());}
 static void dismissSnooze(Context c,String id){if(id==null)return;c.getSharedPreferences("wake",0).edit().remove("snooze:"+id).commit();c.getSystemService(NotificationManager.class).cancel(id.hashCode());}
 static void refresh(Context c){JSONObject s=WakeData.read(c);JSONArray alarms=s.optJSONArray("alarms");Set<String> next=new HashSet<>();long now=System.currentTimeMillis();
  if(alarms!=null)for(int i=0;i<alarms.length();i++){JSONObject a=alarms.optJSONObject(i);if(a==null)continue;String id=a.optString("id");long snooze=c.getSharedPreferences("wake",0).getLong("snooze:"+id,0);long fire=a.optBoolean("enabled")&&snooze>now?snooze:AlarmMath.next(a,now,ZoneId.systemDefault());if(fire>0){at(c,id,fire);next.add(id);}}
  JSONArray checks=s.optJSONArray("wakeChecks");if(checks!=null)for(int i=0;i<checks.length();i++){JSONObject a=checks.optJSONObject(i);if(a!=null&&a.optLong("date")>now){String id="check:"+a.optString("id");at(c,id,a.optLong("date"));next.add(id);}}
  if(s.optBoolean("bedtimeEnabled")){ZonedDateTime date=ZonedDateTime.now().withHour(s.optInt("bedtimeHour",22)).withMinute(s.optInt("bedtimeMinute")).withSecond(0).withNano(0);if(date.toInstant().toEpochMilli()<=now)date=date.plusDays(1);at(c,"bedtime",date.toInstant().toEpochMilli());next.add("bedtime");}
  Set<String> prior=c.getSharedPreferences("wake",0).getStringSet("scheduled",Set.of());for(String id:prior)if(!next.contains(id))cancel(c,id);c.getSharedPreferences("wake",0).edit().putStringSet("scheduled",next).commit();
 }
 static void channels(Context c){NotificationManager nm=c.getSystemService(NotificationManager.class);NotificationChannel alarm=new NotificationChannel("alarms","Morning alarms",NotificationManager.IMPORTANCE_HIGH);alarm.setSound(null,null);alarm.setDescription("Your wake-up alarms and optional stay-awake checks");alarm.setLockscreenVisibility(Notification.VISIBILITY_PUBLIC);nm.createNotificationChannel(alarm);nm.createNotificationChannel(new NotificationChannel("snooze","Snooze countdown",NotificationManager.IMPORTANCE_LOW));nm.createNotificationChannel(new NotificationChannel("bedtime","Bedtime reminder",NotificationManager.IMPORTANCE_DEFAULT));}
}
